    let mut main_geometry = edge0_points;
    main_geometry.extend(edge2_points.iter().skip(1).copied());
    let mut graph = RegionGraph::new();
    let mut network = TransitNetwork::new();
    let config = crate::simulation::core::config::WorldConfig::default();
    let mut zoning = crate::simulation::grid::zoning::ZoningSystem::new(&config);
    let mut allocator = crate::simulation::buildings::allocator::BuildingAllocator::new();
    network.add_road(
        &mut graph,
        main_geometry,
        1,
        1,
        EdgeClass::Standard,
        &mut zoning,
        &mut allocator,
    );
    network.road_surface.compile_dirty(&graph, &terrain);
    network.add_road(
        &mut graph,
        edge1_points,
        1,
        1,
        EdgeClass::Standard,
        &mut zoning,
        &mut allocator,
    );
    network.road_surface.compile_dirty(&graph, &terrain);

    let center = (0..graph.node_count() as u32)
        .find(|&node_id| {
            graph
                .node_adjacency(node_id)
                .iter()
                .filter(|&&edge_idx| !graph.edge(edge_idx).deleted)
                .count()
                == 3
        })
        .expect("edit path must create the regenerated elevated hill 3-way junction node");
    let piece = network
        .road_surface
        .compiled_visual_node_pieces()
        .get(&center)
        .unwrap_or_else(|| {
            panic!(
                "regenerated elevated hill 3-way JunctionN must compile full pipeline: {}",
                canonical_junction_pipeline_report(&network.road_surface, &graph, center)
            )
        });
    assert_eq!(piece.kind, RoadSurfaceVisualNodePieceKind::JunctionN);
    assert_node_piece_uses_band_owned_regions(piece);
    assert_node_earthwork_faces_have_footprint_provenance(piece);
